import{_ as e,o as r,c as a,a3 as s}from"./chunks/framework.lx4Uzxpr.js";const p=JSON.parse('{"title":"测试方法论：把真实世界的随机性变成可控变量","description":"机器人测试的根本困难是真实世界不可复现；方法论的核心是把随机性逐层固化——单测固化输入、仿真固化世界、录包固化现场、指标固化评价","frontmatter":{"title":"测试方法论：把真实世界的随机性变成可控变量","date":"2026-10-24T00:00:00.000Z","tags":["机器人","系统","测试"],"category":"notes","description":"机器人测试的根本困难是真实世界不可复现；方法论的核心是把随机性逐层固化——单测固化输入、仿真固化世界、录包固化现场、指标固化评价","sidebar":false},"headers":[],"relativePath":"notes/机器人/系统与仿真/testing.md","filePath":"notes/机器人/系统与仿真/testing.md"}'),o={name:"notes/机器人/系统与仿真/testing.md"};function n(d,t,i,l,h,c){return r(),a("div",null,t[0]||(t[0]=[s('<h1 id="测试方法论" tabindex="-1">测试方法论 <a class="header-anchor" href="#测试方法论" aria-label="Permalink to “测试方法论”">​</a></h1><p><strong>一句话定义：机器人测试 = 在真实世界不可复现的约束下，用&quot;逐层固化随机性&quot;的办法让问题可重复、指标可比较、回归可执行。</strong></p><h2 id="内核-为什么机器人测试比软件测试难" tabindex="-1">内核：为什么机器人测试比软件测试难 <a class="header-anchor" href="#内核-为什么机器人测试比软件测试难" aria-label="Permalink to “内核：为什么机器人测试比软件测试难”">​</a></h2><p>普通软件的输入是确定的，机器人软件的输入是<strong>物理世界</strong>——同一份代码今天跑和明天跑，光照、地面、电池电压、传动温度都不同。于是&quot;上次好的现在坏了&quot;三种可能：代码退化、环境变了、器件漂移（<a href="/notes/机器人/硬件与电子/encoders" class="term-link" title="位置反馈的真值来源：增量式数脉冲，绝对式读码">编码器</a>零位、<a href="/notes/机器人/结构与机构/reducers" class="term-link" title="功率守恒下力矩换转速；背隙与刚度是它的两个性格参数">减速器</a>温升）。测试方法论的内核动作：<strong>把三者解耦</strong>——</p><ul><li>环境随机性 → 仿真固化世界（同一场景种子可重跑）；</li><li>现场随机性 → 录包固化现场（<a href="/notes/机器人/软件与中间件/time-sync-replay" class="term-link" title="时间戳在采集层打、全链路透传；录包把现场变成可重放数据">数据回放与时间同步</a>）；</li><li>器件随机性 → 标定与自检固化状态（<a href="/notes/机器人/感知与估计/sensor-calibration" class="term-link" title="估计内参与外参使多源数据自洽；手眼标定 AX=XB">传感器标定</a>）。</li></ul><p>解耦之后，&quot;坏了&quot;总能归位到某一层，修复才有的放矢。</p><h2 id="规则与行为" tabindex="-1">规则与行为 <a class="header-anchor" href="#规则与行为" aria-label="Permalink to “规则与行为”">​</a></h2><p><strong>测试金字塔规则</strong>（越往上越贵越慢，问题尽量在下面拦住）：</p><table tabindex="0"><thead><tr><th>层</th><th>固化什么</th><th>速度</th><th>拦截什么</th></tr></thead><tbody><tr><td>单元测试</td><td>输入输出</td><td>秒</td><td>逻辑错误（变换、解析、状态转移）</td></tr><tr><td>仿真集成</td><td>世界 + 全软件链</td><td>分钟</td><td>模块接缝、时序、参数</td></tr><tr><td>HIL 硬件在环</td><td>真硬件 + 虚世界</td><td>分钟–小时</td><td>实时性、驱动、总线</td></tr><tr><td>整机场景</td><td>真机 + 真世界</td><td>小时</td><td>真实环境的最终确认</td></tr></tbody></table><p>规则：<strong>代码合并前必须过单测 + 仿真回归；整机场景只做抽样确认</strong>——把整机时间留给仿真拦不住的问题。</p><p><strong>指标体系规则</strong>：每个动作定义可测指标（到位精度/完成时间/成功率/异常恢复率），每次测试输出<strong>与历史可比的数字</strong>而不是&quot;感觉还行&quot;。指标要配测试条件（负载/电池电压/温度）——不带条件的成功率没有意义。舵机类测试的最小指标集：零位重复性、定位精度、响应延迟、温升曲线、堵转保护。</p><p><strong>消融规则</strong>：改了两个变量后性能变化，无法归因——<strong>一次只动一个变量</strong>，其余用上一条的可比指标冻结。这与<a href="/notes/机器人/系统与仿真/integration" class="term-link" title="把模块间隐式假设（时钟/坐标系/单位/方向/时序）显式化验证">整机联调流程</a>&quot;每阶段只引入一个新变量&quot;是同一纪律的两面。</p><p><strong>异常注入规则</strong>：正常路径人人会测，故障路径不注入永远不执行——拔传感器、掉包、电压跌落、堵转，逐项注入并核对进入预期安全态（与联调检查单共享用例）。</p><h2 id="抽象-测试即资产" tabindex="-1">抽象：测试即资产 <a class="header-anchor" href="#抽象-测试即资产" aria-label="Permalink to “抽象：测试即资产”">​</a></h2><p>抽象后，测试的产出不是&quot;通过/失败&quot;，而是三类<strong>资产</strong>：可重放的录包库（问题复现用例）、可自动执行的回归脚本（<a href="/notes/机器人/系统与仿真/integration" class="term-link" title="把模块间隐式假设（时钟/坐标系/单位/方向/时序）显式化验证">整机联调流程</a>标准脚本的延伸）、带条件的指标历史（性能退化趋势）。三者进 CI 的闭环：<strong>每次提交 → 仿真回归 → 指标对比 → 超阈值报警</strong>。至此&quot;先明确流程、再写脚本&quot;的工作方式有了完整落点：流程固化成检查单与脚本，脚本产生资产，资产反过来守护流程。</p>',15)]))}const u=e(o,[["render",n]]);export{p as __pageData,u as default};
